package btk.bot.reference;

/**
 * Frozen constants of the {@code boss-v1} reference, generated by tools/boss_proxy/fit_boss_target.py and
 * fit_boss_hold.py / fit_boss_build.py from the 855-game boss replay corpus (docs/boss-proxy-v1.md).
 * Conditional logit on 20088 commitment decisions: held-out top-1 0.510 (uniform 0.045).
 * Regenerating them is a new reference version; never hand-edit.
 */
final class BossWeights {
    private BossWeights() {}

    /** Raw per-unit logit weights; feature order: dOpp, dOwn, oppCells, oppActive, ownCells, oppPlacedPrev2,
     *  instab, oppRouteTraffic, routesAny, adjTownRegion, closes, neutralCells, log1p(freeCells). */
    static final double[] TARGET = {
        +0.137316  /* dOpp */,
        -0.111814  /* dOwn */,
        +0.775046  /* oppCells */,
        -0.003927  /* oppActive */,
        -0.282833  /* ownCells */,
        +0.291303  /* oppPlacedPrev2 */,
        +0.884541  /* instab */,
        +0.371747  /* oppRouteTraffic */,
        -0.001751  /* routesAny */,
        +0.368378  /* adjTownRegion */,
        -3.437223  /* closes */,
        +0.155573  /* neutralCells */,
        +0.148325  /* logFree */
    };
    /** Hold the committed target unless another region's logit exceeds it by this margin (observed hold rate 0.835 -> 0.845). */
    static final double ABANDON_MARGIN = 1.0;
    /** Project stickiness: the boss finishes what it starts (top-1 pair agreement 0.24 -> 0.50 at 3.0). */
    static final double ROUTE_STICKINESS = 3.0;
    /** Cost exponent of the project value; 0 fitted best. */
    static final double COST_PREFERENCE = 0.0;
}
